// // // // // // // // // // // // // // // // // // // // // import React, { useState, useContext, useEffect, useCallback } from 'react';
// // // // // // // // // // // // // // // // // // // // // import {
// // // // // // // // // // // // // // // // // // // // //   View,
// // // // // // // // // // // // // // // // // // // // //   Text,
// // // // // // // // // // // // // // // // // // // // //   StyleSheet,
// // // // // // // // // // // // // // // // // // // // //   SafeAreaView,
// // // // // // // // // // // // // // // // // // // // //   StatusBar,
// // // // // // // // // // // // // // // // // // // // //   FlatList,
// // // // // // // // // // // // // // // // // // // // //   TouchableOpacity,
// // // // // // // // // // // // // // // // // // // // //   Alert,
// // // // // // // // // // // // // // // // // // // // //   RefreshControl,
// // // // // // // // // // // // // // // // // // // // // } from 'react-native';
// // // // // // // // // // // // // // // // // // // // // import Icon from 'react-native-vector-icons/Ionicons';
// // // // // // // // // // // // // // // // // // // // // import { OrderContext } from '../../context/OrderContext';
// // // // // // // // // // // // // // // // // // // // // import { supabase } from '../../services/supabaseClient';

// // // // // // // // // // // // // // // // // // // // // const OrdersScreen: React.FC = ({ navigation }: any) => {
// // // // // // // // // // // // // // // // // // // // //   const [activeTab, setActiveTab] = useState<'current' | 'past' | 'cancelled'>('current');
// // // // // // // // // // // // // // // // // // // // //   const [refreshing, setRefreshing] = useState(false);
// // // // // // // // // // // // // // // // // // // // //   const [localOrders, setLocalOrders] = useState<any[]>([]);
// // // // // // // // // // // // // // // // // // // // //   const { orders, updateOrderStatus } = useContext(OrderContext);

// // // // // // // // // // // // // // // // // // // // //   // ✅ Load orders from context into local state
// // // // // // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // // // // // //     console.log('📦 Orders updated in context:', orders.length);
// // // // // // // // // // // // // // // // // // // // //     setLocalOrders([...orders]);
// // // // // // // // // // // // // // // // // // // // //   }, [orders]);

// // // // // // // // // // // // // // // // // // // // //   // ✅ Get filtered orders from local state
// // // // // // // // // // // // // // // // // // // // //   const getFilteredOrders = (tab: 'current' | 'past' | 'cancelled') => {
// // // // // // // // // // // // // // // // // // // // //     return localOrders.filter((order: any) => {
// // // // // // // // // // // // // // // // // // // // //       if (tab === 'current') {
// // // // // // // // // // // // // // // // // // // // //         return order.status !== 'Delivered' && order.status !== 'Cancelled';
// // // // // // // // // // // // // // // // // // // // //       } else if (tab === 'past') {
// // // // // // // // // // // // // // // // // // // // //         return order.status === 'Delivered';
// // // // // // // // // // // // // // // // // // // // //       } else {
// // // // // // // // // // // // // // // // // // // // //         return order.status === 'Cancelled';
// // // // // // // // // // // // // // // // // // // // //       }
// // // // // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   const filteredOrders = getFilteredOrders(activeTab);

// // // // // // // // // // // // // // // // // // // // //   const getStatusColor = (status: string) => {
// // // // // // // // // // // // // // // // // // // // //     switch (status) {
// // // // // // // // // // // // // // // // // // // // //       case 'Delivered': return '#28a745';
// // // // // // // // // // // // // // // // // // // // //       case 'On the way': return '#17a2b8';
// // // // // // // // // // // // // // // // // // // // //       case 'Preparing': return '#ffc107';
// // // // // // // // // // // // // // // // // // // // //       case 'Placed': return '#ffc107';
// // // // // // // // // // // // // // // // // // // // //       case 'Ready': return '#28a745';
// // // // // // // // // // // // // // // // // // // // //       case 'Cancelled': return '#dc3545';
// // // // // // // // // // // // // // // // // // // // //       default: return '#7e808c';
// // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   const getStatusIcon = (status: string) => {
// // // // // // // // // // // // // // // // // // // // //     switch (status) {
// // // // // // // // // // // // // // // // // // // // //       case 'Delivered': return 'checkmark-circle';
// // // // // // // // // // // // // // // // // // // // //       case 'On the way': return 'bicycle';
// // // // // // // // // // // // // // // // // // // // //       case 'Preparing': return 'time';
// // // // // // // // // // // // // // // // // // // // //       case 'Placed': return 'time';
// // // // // // // // // // // // // // // // // // // // //       case 'Ready': return 'checkmark-circle';
// // // // // // // // // // // // // // // // // // // // //       case 'Cancelled': return 'close-circle';
// // // // // // // // // // // // // // // // // // // // //       default: return 'time';
// // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   const formatDate = (dateString: string) => {
// // // // // // // // // // // // // // // // // // // // //     const date = new Date(dateString);
// // // // // // // // // // // // // // // // // // // // //     const now = new Date();
// // // // // // // // // // // // // // // // // // // // //     const diff = now.getTime() - date.getTime();
// // // // // // // // // // // // // // // // // // // // //     const hours = Math.floor(diff / (1000 * 60 * 60));

// // // // // // // // // // // // // // // // // // // // //     if (hours < 24) {
// // // // // // // // // // // // // // // // // // // // //       return `Today • ${date.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}`;
// // // // // // // // // // // // // // // // // // // // //     } else if (hours < 48) {
// // // // // // // // // // // // // // // // // // // // //       return 'Yesterday';
// // // // // // // // // // // // // // // // // // // // //     } else {
// // // // // // // // // // // // // // // // // // // // //       return date.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
// // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   // ✅ Cancel function - updates local state immediately, then jumps to Cancelled tab
// // // // // // // // // // // // // // // // // // // // //   const handleCancelOrder = (item: any) => {
// // // // // // // // // // // // // // // // // // // // //     Alert.alert(
// // // // // // // // // // // // // // // // // // // // //       '❌ Cancel Order',
// // // // // // // // // // // // // // // // // // // // //       `Are you sure you want to cancel this order?\n\nOrder: ${item.restaurantName}\nTotal: ₹${item.total}`,
// // // // // // // // // // // // // // // // // // // // //       [
// // // // // // // // // // // // // // // // // // // // //         { text: 'No', style: 'cancel' },
// // // // // // // // // // // // // // // // // // // // //         {
// // // // // // // // // // // // // // // // // // // // //           text: 'Yes, Cancel',
// // // // // // // // // // // // // // // // // // // // //           style: 'destructive',
// // // // // // // // // // // // // // // // // // // // //           onPress: async () => {
// // // // // // // // // // // // // // // // // // // // //             try {
// // // // // // // // // // // // // // // // // // // // //               console.log('🔄 Cancelling order:', item.id);

// // // // // // // // // // // // // // // // // // // // //               // ✅ 1. Update local state immediately.
// // // // // // // // // // // // // // // // // // // // //               // Because getFilteredOrders() excludes 'Cancelled' orders from the
// // // // // // // // // // // // // // // // // // // // //               // 'current' tab, this single state update is what makes the order
// // // // // // // // // // // // // // // // // // // // //               // disappear from Current automatically — no extra code needed.
// // // // // // // // // // // // // // // // // // // // //               setLocalOrders(prevOrders =>
// // // // // // // // // // // // // // // // // // // // //                 prevOrders.map(order =>
// // // // // // // // // // // // // // // // // // // // //                   order.id === item.id
// // // // // // // // // // // // // // // // // // // // //                     ? { ...order, status: 'Cancelled' }
// // // // // // // // // // // // // // // // // // // // //                     : order
// // // // // // // // // // // // // // // // // // // // //                 )
// // // // // // // // // // // // // // // // // // // // //               );

// // // // // // // // // // // // // // // // // // // // //               // ✅ 2. Update context so other screens stay in sync
// // // // // // // // // // // // // // // // // // // // //               updateOrderStatus(item.id, 'Cancelled');

// // // // // // // // // // // // // // // // // // // // //               // ✅ 3. Update Supabase (orders table)
// // // // // // // // // // // // // // // // // // // // //               try {
// // // // // // // // // // // // // // // // // // // // //                 await supabase
// // // // // // // // // // // // // // // // // // // // //                   .from('orders')
// // // // // // // // // // // // // // // // // // // // //                   .update({ status: 'Cancelled', updated_at: new Date().toISOString() })
// // // // // // // // // // // // // // // // // // // // //                   .eq('order_id', item.id);
// // // // // // // // // // // // // // // // // // // // //                 console.log('✅ Updated Supabase orders');
// // // // // // // // // // // // // // // // // // // // //               } catch (e) {
// // // // // // // // // // // // // // // // // // // // //                 console.error('Supabase order error:', e);
// // // // // // // // // // // // // // // // // // // // //               }

// // // // // // // // // // // // // // // // // // // // //               // ✅ 3b. Update Supabase (deliveries table)
// // // // // // // // // // // // // // // // // // // // //               try {
// // // // // // // // // // // // // // // // // // // // //                 await supabase
// // // // // // // // // // // // // // // // // // // // //                   .from('deliveries')
// // // // // // // // // // // // // // // // // // // // //                   .update({ status: 'Cancelled', updated_at: new Date().toISOString() })
// // // // // // // // // // // // // // // // // // // // //                   .eq('order_id', item.id);
// // // // // // // // // // // // // // // // // // // // //                 console.log('✅ Updated Supabase deliveries');
// // // // // // // // // // // // // // // // // // // // //               } catch (e) {
// // // // // // // // // // // // // // // // // // // // //                 console.error('Supabase delivery error:', e);
// // // // // // // // // // // // // // // // // // // // //               }

// // // // // // // // // // // // // // // // // // // // //               // ✅ 4. Switch to the Cancelled tab so the user sees the order land there
// // // // // // // // // // // // // // // // // // // // //               setActiveTab('cancelled');

// // // // // // // // // // // // // // // // // // // // //               Alert.alert(
// // // // // // // // // // // // // // // // // // // // //                 '✅ Order Cancelled',
// // // // // // // // // // // // // // // // // // // // //                 `Your order has been cancelled successfully.`,
// // // // // // // // // // // // // // // // // // // // //                 [{ text: 'OK' }]
// // // // // // // // // // // // // // // // // // // // //               );
// // // // // // // // // // // // // // // // // // // // //             } catch (error) {
// // // // // // // // // // // // // // // // // // // // //               console.error('Error cancelling order:', error);
// // // // // // // // // // // // // // // // // // // // //               Alert.alert('Error', 'Failed to cancel order. Please try again.');
// // // // // // // // // // // // // // // // // // // // //             }
// // // // // // // // // // // // // // // // // // // // //           },
// // // // // // // // // // // // // // // // // // // // //         },
// // // // // // // // // // // // // // // // // // // // //       ]
// // // // // // // // // // // // // // // // // // // // //     );
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   // ✅ Handle View Order Details
// // // // // // // // // // // // // // // // // // // // //   const handleViewOrder = (item: any) => {
// // // // // // // // // // // // // // // // // // // // //     navigation.navigate('OrderTracking', {
// // // // // // // // // // // // // // // // // // // // //       orderId: item.id,
// // // // // // // // // // // // // // // // // // // // //       total: item.total,
// // // // // // // // // // // // // // // // // // // // //       items: item.items,
// // // // // // // // // // // // // // // // // // // // //       restaurantName: item.restaurantName,
// // // // // // // // // // // // // // // // // // // // //       paymentMethod: item.paymentMethod || 'Cash on Delivery',
// // // // // // // // // // // // // // // // // // // // //       paymentStatus: item.paymentStatus || 'Confirmed',
// // // // // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   // ✅ Refresh handler
// // // // // // // // // // // // // // // // // // // // //   const onRefresh = useCallback(() => {
// // // // // // // // // // // // // // // // // // // // //     setRefreshing(true);
// // // // // // // // // // // // // // // // // // // // //     setLocalOrders([...orders]);
// // // // // // // // // // // // // // // // // // // // //     setTimeout(() => {
// // // // // // // // // // // // // // // // // // // // //       setRefreshing(false);
// // // // // // // // // // // // // // // // // // // // //     }, 1000);
// // // // // // // // // // // // // // // // // // // // //   }, [orders]);

// // // // // // // // // // // // // // // // // // // // //   // ✅ Get count for each tab
// // // // // // // // // // // // // // // // // // // // //   const getTabCount = (tab: 'current' | 'past' | 'cancelled') => {
// // // // // // // // // // // // // // // // // // // // //     return getFilteredOrders(tab).length;
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   const renderOrder = ({ item }: { item: any }) => {
// // // // // // // // // // // // // // // // // // // // //     const isCurrent = activeTab === 'current';
// // // // // // // // // // // // // // // // // // // // //     const isCancelled = activeTab === 'cancelled';
// // // // // // // // // // // // // // // // // // // // //     const isDelivered = item.status === 'Delivered';
// // // // // // // // // // // // // // // // // // // // //     const isPast = activeTab === 'past';
// // // // // // // // // // // // // // // // // // // // //     // IMPORTANT: this checks item.status (not activeTab) so that the moment
// // // // // // // // // // // // // // // // // // // // //     // the order's status flips to 'Cancelled' in local state, the Cancel
// // // // // // // // // // // // // // // // // // // // //     // button hides itself even before the tab switch finishes.
// // // // // // // // // // // // // // // // // // // // //     const showCancelButton = isCurrent && !isDelivered && item.status !== 'Cancelled';

// // // // // // // // // // // // // // // // // // // // //     return (
// // // // // // // // // // // // // // // // // // // // //       <TouchableOpacity
// // // // // // // // // // // // // // // // // // // // //         style={[styles.orderCard, isCancelled && styles.cancelledCard]}
// // // // // // // // // // // // // // // // // // // // //         onPress={() => handleViewOrder(item)}
// // // // // // // // // // // // // // // // // // // // //         activeOpacity={0.7}
// // // // // // // // // // // // // // // // // // // // //       >
// // // // // // // // // // // // // // // // // // // // //         <View style={styles.orderHeader}>
// // // // // // // // // // // // // // // // // // // // //           <View style={styles.orderLeft}>
// // // // // // // // // // // // // // // // // // // // //             <Text style={styles.orderRestaurant}>{item.restaurantName}</Text>
// // // // // // // // // // // // // // // // // // // // //             <Text style={styles.orderDetails}>
// // // // // // // // // // // // // // // // // // // // //               {item.items.length} {item.items.length === 1 ? 'item' : 'items'} • ₹{item.total}
// // // // // // // // // // // // // // // // // // // // //             </Text>
// // // // // // // // // // // // // // // // // // // // //             <Text style={styles.orderId}>Order #{item.id.slice(0, 8)}</Text>
// // // // // // // // // // // // // // // // // // // // //           </View>
// // // // // // // // // // // // // // // // // // // // //           <View style={[styles.statusBadge, { backgroundColor: getStatusColor(item.status) + '20' }]}>
// // // // // // // // // // // // // // // // // // // // //             <Icon name={getStatusIcon(item.status)} size={14} color={getStatusColor(item.status)} />
// // // // // // // // // // // // // // // // // // // // //             <Text style={[styles.statusText, { color: getStatusColor(item.status) }]}>
// // // // // // // // // // // // // // // // // // // // //               {item.status}
// // // // // // // // // // // // // // // // // // // // //             </Text>
// // // // // // // // // // // // // // // // // // // // //           </View>
// // // // // // // // // // // // // // // // // // // // //         </View>

// // // // // // // // // // // // // // // // // // // // //         <View style={styles.orderFooter}>
// // // // // // // // // // // // // // // // // // // // //           <Text style={styles.orderTime}>{formatDate(item.createdAt)}</Text>
// // // // // // // // // // // // // // // // // // // // //           <View style={styles.footerButtons}>

// // // // // // // // // // // // // // // // // // // // //             {/* ✅ Cancel Button - Only on Current tab for non-delivered/non-cancelled orders */}
// // // // // // // // // // // // // // // // // // // // //             {showCancelButton && (
// // // // // // // // // // // // // // // // // // // // //               <TouchableOpacity
// // // // // // // // // // // // // // // // // // // // //                 style={styles.cancelButton}
// // // // // // // // // // // // // // // // // // // // //                 onPress={(e) => {
// // // // // // // // // // // // // // // // // // // // //                   // Stop the tap from also triggering the parent card's
// // // // // // // // // // // // // // // // // // // // //                   // onPress (handleViewOrder), which could otherwise fire
// // // // // // // // // // // // // // // // // // // // //                   // in the same gesture and navigate you away before the
// // // // // // // // // // // // // // // // // // // // //                   // cancel alert even opens.
// // // // // // // // // // // // // // // // // // // // //                   e.stopPropagation?.();
// // // // // // // // // // // // // // // // // // // // //                   handleCancelOrder(item);
// // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // //                 activeOpacity={0.8}
// // // // // // // // // // // // // // // // // // // // //               >
// // // // // // // // // // // // // // // // // // // // //                 <Icon name="close-outline" size={14} color="#dc3545" />
// // // // // // // // // // // // // // // // // // // // //                 <Text style={styles.cancelButtonText}>Cancel</Text>
// // // // // // // // // // // // // // // // // // // // //               </TouchableOpacity>
// // // // // // // // // // // // // // // // // // // // //             )}

// // // // // // // // // // // // // // // // // // // // //             {/* ✅ View Button - For Past and Cancelled tabs */}
// // // // // // // // // // // // // // // // // // // // //             {(isPast || isCancelled) && (
// // // // // // // // // // // // // // // // // // // // //               <TouchableOpacity
// // // // // // // // // // // // // // // // // // // // //                 style={styles.viewButton}
// // // // // // // // // // // // // // // // // // // // //                 onPress={(e) => {
// // // // // // // // // // // // // // // // // // // // //                   e.stopPropagation?.();
// // // // // // // // // // // // // // // // // // // // //                   handleViewOrder(item);
// // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // //                 activeOpacity={0.8}
// // // // // // // // // // // // // // // // // // // // //               >
// // // // // // // // // // // // // // // // // // // // //                 <Icon name="eye-outline" size={14} color="#fc8019" />
// // // // // // // // // // // // // // // // // // // // //                 <Text style={styles.viewButtonText}>View</Text>
// // // // // // // // // // // // // // // // // // // // //               </TouchableOpacity>
// // // // // // // // // // // // // // // // // // // // //             )}

// // // // // // // // // // // // // // // // // // // // //           </View>
// // // // // // // // // // // // // // // // // // // // //         </View>
// // // // // // // // // // // // // // // // // // // // //       </TouchableOpacity>
// // // // // // // // // // // // // // // // // // // // //     );
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   return (
// // // // // // // // // // // // // // // // // // // // //     <SafeAreaView style={styles.container}>
// // // // // // // // // // // // // // // // // // // // //       <StatusBar barStyle="dark-content" backgroundColor="#ffffff" />

// // // // // // // // // // // // // // // // // // // // //       <View style={styles.header}>
// // // // // // // // // // // // // // // // // // // // //         <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
// // // // // // // // // // // // // // // // // // // // //           <Icon name="arrow-back" size={24} color="#282c3f" />
// // // // // // // // // // // // // // // // // // // // //         </TouchableOpacity>
// // // // // // // // // // // // // // // // // // // // //         <Text style={styles.headerTitle}>My Orders</Text>
// // // // // // // // // // // // // // // // // // // // //         <TouchableOpacity
// // // // // // // // // // // // // // // // // // // // //           style={styles.headerRight}
// // // // // // // // // // // // // // // // // // // // //           onPress={() => navigation.navigate('Home')}
// // // // // // // // // // // // // // // // // // // // //         >
// // // // // // // // // // // // // // // // // // // // //           <Icon name="home-outline" size={24} color="#fc8019" />
// // // // // // // // // // // // // // // // // // // // //         </TouchableOpacity>
// // // // // // // // // // // // // // // // // // // // //       </View>

// // // // // // // // // // // // // // // // // // // // //       <View style={styles.tabsContainer}>
// // // // // // // // // // // // // // // // // // // // //         {[
// // // // // // // // // // // // // // // // // // // // //           { id: 'current', label: 'Current' },
// // // // // // // // // // // // // // // // // // // // //           { id: 'past', label: 'Past' },
// // // // // // // // // // // // // // // // // // // // //           { id: 'cancelled', label: 'Cancelled' },
// // // // // // // // // // // // // // // // // // // // //         ].map((tab) => (
// // // // // // // // // // // // // // // // // // // // //           <TouchableOpacity
// // // // // // // // // // // // // // // // // // // // //             key={tab.id}
// // // // // // // // // // // // // // // // // // // // //             style={[styles.tab, activeTab === tab.id && styles.activeTab]}
// // // // // // // // // // // // // // // // // // // // //             onPress={() => setActiveTab(tab.id as 'current' | 'past' | 'cancelled')}
// // // // // // // // // // // // // // // // // // // // //             activeOpacity={0.7}
// // // // // // // // // // // // // // // // // // // // //           >
// // // // // // // // // // // // // // // // // // // // //             <Text style={[styles.tabText, activeTab === tab.id && styles.activeTabText]}>
// // // // // // // // // // // // // // // // // // // // //               {tab.label}
// // // // // // // // // // // // // // // // // // // // //             </Text>
// // // // // // // // // // // // // // // // // // // // //             {getTabCount(tab.id as 'current' | 'past' | 'cancelled') > 0 && (
// // // // // // // // // // // // // // // // // // // // //               <View style={styles.badge}>
// // // // // // // // // // // // // // // // // // // // //                 <Text style={styles.badgeText}>
// // // // // // // // // // // // // // // // // // // // //                   {getTabCount(tab.id as 'current' | 'past' | 'cancelled')}
// // // // // // // // // // // // // // // // // // // // //                 </Text>
// // // // // // // // // // // // // // // // // // // // //               </View>
// // // // // // // // // // // // // // // // // // // // //             )}
// // // // // // // // // // // // // // // // // // // // //             {activeTab === tab.id && <View style={styles.tabIndicator} />}
// // // // // // // // // // // // // // // // // // // // //           </TouchableOpacity>
// // // // // // // // // // // // // // // // // // // // //         ))}
// // // // // // // // // // // // // // // // // // // // //       </View>

// // // // // // // // // // // // // // // // // // // // //       <FlatList
// // // // // // // // // // // // // // // // // // // // //         data={filteredOrders}
// // // // // // // // // // // // // // // // // // // // //         renderItem={renderOrder}
// // // // // // // // // // // // // // // // // // // // //         keyExtractor={(item) => item.id}
// // // // // // // // // // // // // // // // // // // // //         contentContainerStyle={styles.ordersList}
// // // // // // // // // // // // // // // // // // // // //         showsVerticalScrollIndicator={false}
// // // // // // // // // // // // // // // // // // // // //         refreshControl={
// // // // // // // // // // // // // // // // // // // // //           <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
// // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // //         ListEmptyComponent={
// // // // // // // // // // // // // // // // // // // // //           <View style={styles.emptyContainer}>
