// // // // // // // // // // // // // // // // // // // // //               {activeTab === 'cancelled' && 'Cancelled orders will appear here'}
// // // // // // // // // // // // // // // // // // // // //             </Text>
// // // // // // // // // // // // // // // // // // // // //           </View>
// // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // //       />
// // // // // // // // // // // // // // // // // // // // //     </SafeAreaView>
// // // // // // // // // // // // // // // // // // // // //   );
