// // // // // // // // // // // // // // // //               </TouchableOpacity>
// // // // // // // // // // // // // // // //             )}
            
// // // // // // // // // // // // // // // //             {/* ✅ View Button - For Past and Cancelled tabs */}
// // // // // // // // // // // // // // // //             {showViewButton && (
// // // // // // // // // // // // // // // //               <TouchableOpacity
// // // // // // // // // // // // // // // //                 style={styles.viewButton}
// // // // // // // // // // // // // // // //                 onPress={handleViewPress}
// // // // // // // // // // // // // // // //                 activeOpacity={0.8}
// // // // // // // // // // // // // // // //                 hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
// // // // // // // // // // // // // // // //               >
